input_csv = "data/recipes_dataset.csv"
output_csv_1 = "data/recipes_dataset.csv"
output_csv_2 = r"C:\Users\Win11 Pro\Downloads\recipes_dataset.csv"

# อ่านไฟล์เดิมโดยใช้ utf-8-sig เพื่อตัด BOM (\ufeff)
rows = []
fieldnames = []
with open(input_csv, mode="r", encoding="utf-8-sig") as f:
    reader = csv.DictReader(f)
    fieldnames = [col.replace('\ufeff', '') for col in reader.fieldnames]
    for r in reader:
        # ล้าง key ที่มี BOM
        clean_row = {k.replace('\ufeff', ''): v for k, v in r.items()}
        rows.append(clean_row)

# เพิ่มคอลัมน์ steps ถ้ายังไม่มี
if "steps" not in fieldnames:
    fieldnames.append("steps")

# เติมขั้นตอนของแต่ละเมนู
for r in rows:
    rid = r.get("recipe_id", "").strip()
    r["steps"] = RECIPE_STEPS.get(rid, "1. เตรียมวัตถุดิบ | 2. ปรุงตามขั้นตอน | 3. จัดเสิร์ฟ")

# บันทึกไฟล์ทั้ง 2 ที่ (ใช้ utf-8-sig เพื่อให้ Excel บน Windows เปิดแล้วไม่เพี้ยน)
for path in [output_csv_1, output_csv_2]:
    with open(path, mode="w", encoding="utf-8-sig", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)
    print(f"Successfully updated: {path}")

print("Completed enriching all 50 recipes with detailed steps!")
